const headers = $input.first().json.headers ?? {};

const channelId     = headers['x-goog-channel-id']     ?? headers['X-Goog-Channel-Id']     ?? '';
const resourceState = headers['x-goog-resource-state'] ?? headers['X-Goog-Resource-State'] ?? '';
const resourceId    = headers['x-goog-resource-id']    ?? headers['X-Goog-Resource-Id']    ?? '';
const messageNumber = headers['x-goog-message-number'] ?? '0';

console.log(`[google-webhook] channel=${channelId} state=${resourceState} msg=#${messageNumber}`);

if (resourceState === 'sync') {
  console.log('[google-webhook] Handshake sync recebido. Encerrando.');
  return [];
}

if (resourceState !== 'exists' && resourceState !== 'not_exists') {
  console.log(`[google-webhook] Estado desconhecido: ${resourceState}. Ignorando.`);
  return [];
}

if (!channelId) throw new Error('X-Goog-Channel-ID ausente.');

return [{ json: { channelId, resourceState, resourceId, messageNumber } }];

const result   = $input.first().json;
const pushData = $('Validar Push do Google').first().json;

const row = Array.isArray(result) ? result[0] : null;

if (!row?.client_id) {
  console.log(`[google-webhook] Channel ID ${pushData.channelId} não encontrado. Ignorando.`);
  return [];
}

if (row.watch_expiry && new Date(row.watch_expiry).getTime() < Date.now()) {
  console.warn(`[google-webhook] Watch channel expirado para cliente ${row.client_id}. Renovação necessária.`);
}

// Verifica se o token precisa ser renovado antes de chamar a Google API
const expiry = row.token_expiry ? new Date(row.token_expiry).getTime() : 0;
const needsRefresh = expiry - Date.now() < 5 * 60 * 1000;

console.log(`[google-webhook] Evento para cliente: ${row.client_id} | needsRefresh: ${needsRefresh}`);

return [{ json: {
  client_id:     row.client_id,
  access_token:  row.access_token,
  refresh_token: row.refresh_token,
  token_expiry:  row.token_expiry,
  calendar_id:   row.calendar_id ?? 'primary',
  needs_refresh: needsRefresh,
  ...pushData,
} }];

const refreshResult = $input.first().json;
const prev = $('Avaliar Cliente').first().json;
const newToken  = refreshResult.access_token ?? prev.access_token;
const newExpiry = refreshResult.expires_in
  ? new Date(Date.now() + refreshResult.expires_in * 1000).toISOString()
  : prev.token_expiry;

// Persiste o token renovado no Banco A
return [{ json: { ...prev, access_token: newToken, token_expiry: newExpiry, token_was_refreshed: true } }];

const googleResult = $input.first().json;
const ctx = $('Avaliar Cliente').first().json;

const items = googleResult.items ?? [];

if (items.length === 0) {
  console.log(`[google-webhook] Nenhum evento alterado recentemente para cliente ${ctx.client_id}.`);
  return [];
}

return items.map((evt) => ({
  json: {
    client_id:       ctx.client_id,
    google_event_id: evt.id,
    google_status:   evt.status,
    summary:         evt.summary ?? '',
    start_at:        evt.start?.dateTime ?? evt.start?.date,
    end_at:          evt.end?.dateTime   ?? evt.end?.date,
    updated:         evt.updated,
    description:     evt.description ?? '',
  }
}));

const supabaseResult = $input.first().json;
const evt            = $('Processar Eventos').first().json;

const appointment = Array.isArray(supabaseResult) ? supabaseResult[0] : null;

if (!appointment) {
  console.log(`[google-webhook] Evento ${evt.google_event_id} não encontrado no C8 Control. Ignorando.`);
  return [];
}

let newStatus = null;
if (evt.google_status === 'cancelled' && appointment.status !== 'cancelled') {
  newStatus = 'cancelled';
}

const startChanged = evt.start_at && evt.start_at !== appointment.start_at;
const endChanged   = evt.end_at   && evt.end_at   !== appointment.end_at;
const hasChanges   = newStatus !== null || startChanged || endChanged;

if (!hasChanges) {
  console.log(`[google-webhook] Evento ${evt.google_event_id} sem alterações relevantes. Ignorando.`);
  return [];
}

return [{ json: {
  appointment_id: appointment.id,
  new_status:     newStatus,
  new_start_at:   startChanged ? evt.start_at : null,
  new_end_at:     endChanged   ? evt.end_at   : null,
  google_event_id: evt.google_event_id,
  client_id:      evt.client_id,
} }];

const change = $input.first().json;
const patch = {};

if (change.new_status)   patch.status   = change.new_status;
if (change.new_start_at) patch.start_at = change.new_start_at;
if (change.new_end_at)   patch.end_at   = change.new_end_at;

if (change.new_start_at && change.new_end_at) {
  const diffMs = new Date(change.new_end_at).getTime() - new Date(change.new_start_at).getTime();
  patch.duration_min = Math.round(diffMs / 60000);
}

return [{ json: { ...change, patch } }];

const change = $('Montar Patch').first().json;
console.log(`[google-webhook] Agendamento ${change.appointment_id} atualizado. Patch:`, JSON.stringify(change.patch));
return [{ json: { success: true, appointment_id: change.appointment_id, patch: change.patch } }];
